        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(ctx.pathParam("id"))));
        app.get("/messages", ctx -> ctx.json(messages.findAll()));
        app.get("/reports/{name}", this::report);
        app.exception(AppException.class, (e, ctx) ->
